I use playwright to "проверить баннер cookies", async ({ page }) => {
                const consentButton = page.locator(CookieBanner_1.CookieBanner.acceptButton).first();
                try {
                    await consentButton.waitFor({ state: 'visible', timeout: COOKIE_BANNER_TIMEOUT_MS });
                    bannerVisible = true;
                }
                catch (error) {
                    const isTimeoutError = error instanceof Error && error.name === 'TimeoutError';
                    if (!isTimeoutError) {
                        throw error;
                    }
                }
            }
